// HCA 201A Day 3 PowerPoint and Comprehensive Quiz Notes. Keep coverage terms stable across revisions.
const day3Questions = [
  {"id":"hca201a-day3-01-01","scope":"day3","topic":"Anatomical directions & planes","term":"Sagittal plane","prompt":"Three scans divide the body into left and right, front and back, then upper and lower portions. Which sequence matches the scans?","answer":"Sagittal, coronal, transverse","distractors":["Coronal, sagittal, transverse","Sagittal, transverse, coronal","Transverse, coronal, sagittal"],"meaning":"A sagittal section separates left from right. A midsagittal section divides them equally. The coronal plane separates front from back. The transverse plane separates upper from lower.","source":"Day 3 PowerPoint · slide 1"},
  {"id":"hca201a-day3-04-02","scope":"day3","topic":"Anatomical directions & planes","term":"Inferior (caudal)","prompt":"A sore is closer to the feet than the sacrum, even though the client's bed is tilted head-down. Which term describes it relative to the sacrum?","answer":"Inferior","distractors":["Superior","Posterior","Deep"],"meaning":"Inferior, or caudal, still means toward the feet. Bed tilt does not change anatomical orientation.","source":"Day 3 Comprehensive Quiz Notes · p. 2"},
  {"id":"hca201a-day3-04-04","scope":"day3","topic":"Anatomical directions & planes","term":"Posterior","prompt":"The client is supine. A sore on the calf faces the mattress. What calf surface should the HCA document?","answer":"Posterior","distractors":["Anterior","Medial","Lateral"],"meaning":"The back of the calf is posterior even when it faces downward. The front is anterior.","source":"Day 3 Comprehensive Quiz Notes · p. 2"},
  {"id":"hca201a-day3-04-06","scope":"day3","topic":"Anatomical directions & planes","term":"Medial","prompt":"An ankle mark is on the side closest to the other ankle. What term describes that surface?","answer":"Medial","distractors":["Lateral","Proximal","Distal"],"meaning":"The ankle surface toward the midline is medial. The opposite ankle surface is lateral.","source":"Day 3 Comprehensive Quiz Notes · p. 2"},
  {"id":"hca201a-day3-notes-standard-reference-position","scope":"day3","topic":"Anatomical directions & planes","term":"Standard reference position","prompt":"A client is prone with their palms against the mattress. Which reference is used to chart anatomical directions?","answer":"Standing upright, facing forward, with palms and feet facing forward","distractors":["The client's current position with palms against the mattress","Standing upright, facing forward, with palms facing backward","The HCA's position facing the client from the foot of the bed"],"meaning":"Anatomical terms use the standard body position even if the client is lying down or turned.","source":"Day 3 Comprehensive Quiz Notes · p. 2"},
  {"id":"hca201a-day3-notes-proximal-versus-distal","scope":"day3","topic":"Anatomical directions & planes","term":"Proximal versus distal","prompt":"Two marks are on the same forearm, one nearer the elbow and one nearer the wrist. How is the wrist-side mark described relative to the elbow-side mark?","answer":"Distal","distractors":["Proximal","Medial","Superficial"],"meaning":"Distal means farther from the limb's attachment. Medial refers to the body midline and superficial refers to depth.","source":"Day 3 Comprehensive Quiz Notes · p. 2"},
  {"id":"hca201a-day3-notes-superficial-versus-deep","scope":"day3","topic":"Anatomical directions & planes","term":"Superficial versus deep","prompt":"A client has a surface abrasion over a bruised muscle. What describes the abrasion relative to the muscle?","answer":"Superficial","distractors":["Deep","Peripheral","Distal"],"meaning":"Superficial and deep describe distance from the surface, regardless of where the injury is along a limb.","source":"Day 3 Comprehensive Quiz Notes · p. 2"},
  {"id":"hca201a-day3-notes-peripheral-location","scope":"day3","topic":"Anatomical directions & planes","term":"Peripheral location","prompt":"A hand finding is described as peripheral. What reference makes that description meaningful?","answer":"The centre of the body","distractors":["The nearest joint on the limb","The surface of the skin","The direction the client is facing"],"meaning":"Peripheral describes a location away from the centre of the body. Distal is more specifically relative to a limb's attachment or a point of origin.","source":"Day 3 Comprehensive Quiz Notes · p. 2"},
  {"id":"hca201a-day3-02-03","scope":"day3","topic":"Body cavities","term":"Esophagus and trachea","prompt":"Which route comparison avoids confusing the larynx with the trachea and esophagus?","answer":"Larynx is in the neck, while both the trachea and esophagus have thoracic portions.","distractors":["Larynx and trachea lie entirely in the thorax, while the esophagus stays in the neck.","Larynx and esophagus stay in the neck, while the trachea starts below the diaphragm.","Larynx and esophagus are pelvic structures, while only the trachea has a neck portion."],"meaning":"The esophagus and trachea have thoracic portions. The larynx is in the neck.","source":"Day 3 PowerPoint · slide 2","reference":{"label":"Cleveland Clinic","url":"https://my.clevelandclinic.org/health/body/21872-larynx"}},
  {"id":"hca201a-day3-02-05","scope":"day3","topic":"Body cavities","term":"Diaphragm","prompt":"A finding is immediately below the muscular partition under the lungs. Which boundary and region does that describe?","answer":"Below the diaphragm, in the abdominal region","distractors":["Below the peritoneum, in the thoracic region","Below the diaphragm, in the cranial region","Below the pelvis, in the abdominal region"],"meaning":"The diaphragm forms the floor of the thoracic cavity and the roof of the abdominal cavity.","source":"Day 3 PowerPoint · slide 2"},
  {"id":"hca201a-day3-02-08","scope":"day3","topic":"Body cavities","term":"Appendix and cecum","prompt":"Which option correctly pairs an attached structure in the right lower abdomen with the segment that leads into the rectum?","answer":"Appendix attaches to cecum; sigmoid colon leads into rectum.","distractors":["Appendix attaches to sigmoid colon; cecum leads into rectum.","Appendix attaches to ascending colon; sigmoid colon leads into rectum.","Appendix attaches to cecum; ascending colon leads directly into rectum."],"meaning":"The appendix attaches to the cecum. Their exact positions can vary, especially the position of the appendix. The sigmoid colon and rectum are associated with the pelvis.","source":"Day 3 PowerPoint · slide 2"},
  {"id":"hca201a-day3-02-11","scope":"day3","topic":"Body cavities","term":"Peritoneal cavity","prompt":"Which statement correctly distinguishes the peritoneal cavity from the abdominopelvic cavity?","answer":"The peritoneal cavity is the potential space between the peritoneal layers.","distractors":["The two terms refer to every structure below the diaphragm.","The peritoneal cavity is the region behind the peritoneum.","The peritoneal cavity is the subdivision above the diaphragm."],"meaning":"The slide groups these terms. In anatomy, the peritoneal cavity is the potential space between the two layers of peritoneum.","source":"Day 3 PowerPoint · slide 2","reference":{"label":"OpenStax","url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/1-6-anatomical-terminology"}},
  {"id":"hca201a-day3-03-02","scope":"day3","topic":"Body cavities","term":"Retroperitoneal organs","prompt":"Which group lies behind the abdominal peritoneum?","answer":"Kidneys, adrenal glands, and abdominal ureters","distractors":["Stomach, spleen, and jejunum","Heart, lungs, and trachea","Urinary bladder and internal pelvic reproductive organs"],"meaning":"The kidneys, adrenal glands, and abdominal portions of the ureters are retroperitoneal. Retroperitoneal means behind the peritoneum. The abdominal cavity includes many digestive organs and the spleen, while the kidneys lie behind its peritoneal lining.","source":"Day 3 PowerPoint · slide 3"},
  {"id":"hca201a-day3-03-03","scope":"day3","topic":"Body cavities","term":"Bladder and peritoneum","prompt":"How is the resting urinary bladder usually described in relation to the peritoneum?","answer":"Below the peritoneum in the pelvis","distractors":["Suspended within the peritoneal cavity","Behind the abdominal peritoneum beside the kidneys","Over the diaphragm within the thorax"],"meaning":"The slide includes the bladder in its retroperitoneal list. The pelvic bladder is more precisely described as subperitoneal.","source":"Day 3 PowerPoint · slide 3","reference":{"label":"Radiopaedia","url":"https://radiopaedia.org/articles/extraperitoneal-space"}},
  {"id":"hca201a-day3-03-05","scope":"day3","topic":"Body cavities","term":"Dorsal cavity","prompt":"A note describes one finding around the brain and another around the spinal cord. What is the correct cavity hierarchy?","answer":"Cranial and spinal cavities, both dorsal","distractors":["Cranial and spinal cavities, both ventral","Cranial cavity is dorsal and spinal cavity is ventral","Both findings are in the cranial cavity, which is dorsal"],"meaning":"The skull encloses the cranial cavity. Vertebrae form the spinal canal. Both subdivisions are dorsal.","source":"Day 3 Comprehensive Quiz Notes · p. 3"},
  {"id":"hca201a-day3-03-06","scope":"day3","topic":"Body cavities","term":"Ventral cavity","prompt":"One finding involves a lung, a second the stomach, and a third the bladder. Which cavity mapping is correct?","answer":"Thoracic, abdominal, and pelvic respectively, all within the ventral cavity","distractors":["Thoracic, pelvic, and abdominal respectively, all within the ventral cavity","Thoracic, abdominal, and pelvic respectively, all within the dorsal cavity","Abdominal, thoracic, and pelvic respectively, all within the ventral cavity"],"meaning":"The ventral cavity includes the thorax plus the abdominal and pelvic subdivisions of the abdominopelvic cavity.","source":"Day 3 Comprehensive Quiz Notes · p. 3"},
  {"id":"hca201a-day3-05-02","scope":"day3","topic":"Cells, tissues & organs","term":"Cytoplasm","prompt":"Where are many of the cell's organelles suspended, outside the nucleus but inside the outer boundary?","answer":"Cytoplasm","distractors":["Nuclear envelope","Cell membrane","Chromosomes"],"meaning":"The cytoplasm includes the material outside the nucleus but within the cell membrane. Organelles there carry out specialized tasks.","source":"Day 3 Comprehensive Quiz Notes · p. 3"},
  {"id":"hca201a-day3-05-03","scope":"day3","topic":"Cells, tissues & organs","term":"Nucleus","prompt":"Which pairing correctly links a structure to its role in a typical body cell?","answer":"Nucleus stores most DNA and helps direct cell activities.","distractors":["Ribosomes store inherited information and transmit it to daughter cells.","The nuclear membrane controls exchange between the cytoplasm and the outside of the cell.","The cell membrane assembles proteins in the cytoplasm."],"meaning":"Most genetic material is located in the nucleus. Ribosomes assemble proteins.","source":"Day 3 Comprehensive Quiz Notes · p. 3"},
  {"id":"hca201a-day3-05-05","scope":"day3","topic":"Cells, tissues & organs","term":"Cell membrane","prompt":"A change interferes with the cell's ability to regulate what moves between it and its surroundings. Which boundary is directly involved?","answer":"Cell membrane","distractors":["Nuclear membrane","Chromosome","Cytoplasm"],"meaning":"The cell membrane regulates exchange with the surroundings. The nuclear membrane is a separate boundary around the nucleus.","source":"Day 3 Comprehensive Quiz Notes · p. 3"},
  {"id":"hca201a-day3-05-06","scope":"day3","topic":"Cells, tissues & organs","term":"Ribosomes","prompt":"The diagram points to small dots in the cell. Which labelled structures make proteins?","answer":"Ribosomes","distractors":["Nuclear membrane","Cell membrane","Nucleus"],"meaning":"Ribosomes assemble proteins. Ribosomes are the small dots in the cell drawing. The nuclear membrane surrounds the nucleus.","source":"Day 3 PowerPoint · slide 5"},
  {"id":"hca201a-day3-07-04","scope":"day3","topic":"Cells, tissues & organs","term":"Levels of organization example","prompt":"Which sequence matches the example on the slide from simplest to most complex?","answer":"Muscle cell → muscle tissue → stomach → digestive system","distractors":["Muscle tissue → muscle cell → digestive system → stomach","Stomach → muscle cell → muscle tissue → digestive system","Muscle cell → stomach → digestive system → muscle tissue"],"meaning":"The diagram moves from cell to tissue to organ to system. Muscle is one of several tissue types in the stomach. The muscle cell is one example of the body's basic structural and functional unit. Different tissues combine into organs, and organs working together form a system.","source":"Day 3 PowerPoint · slide 7"},
  {"id":"hca201a-day3-notes-chromosomes-and-genes","scope":"day3","topic":"Cells, tissues & organs","term":"Chromosomes and genes","prompt":"Which statement connects the chromosome count to inherited information in most human body cells?","answer":"They have 23 pairs of chromosomes, which carry genes.","distractors":["They have 23 individual chromosomes, and their genes are outside the nucleus.","They have 46 pairs of chromosomes, and their genes are carried by ribosomes.","They have 23 pairs of genes, which are made up of entire chromosomes."],"meaning":"Most nucleated human body cells have 46 chromosomes arranged in 23 pairs. Genes are units of inherited information on chromosomes.","source":"Day 3 Comprehensive Quiz Notes · p. 3"},
  {"id":"hca201a-day3-notes-mitosis-versus-cancer-growth","scope":"day3","topic":"Cells, tissues & organs","term":"Mitosis versus cancer growth","prompt":"Which feature distinguishes normal cell replacement after a minor injury from cancer growth?","answer":"Normal mitosis produces genetically matching daughter cells under growth control.","distractors":["Normal mitosis produces daughter cells only when growth control has failed.","Cancer growth is the regulated replacement of damaged cells.","Normal mitosis makes daughter cells with half the parent's chromosome number."],"meaning":"Normal mitosis supports growth and repair. Cancer involves loss of normal control over growth and division.","source":"Day 3 Comprehensive Quiz Notes · p. 3"},
  {"id":"hca201a-day3-notes-epithelial-cell-shapes","scope":"day3","topic":"Cells, tissues & organs","term":"Epithelial cell shapes","prompt":"Which mapping correctly describes common epithelial cell shapes?","answer":"Squamous flat, cuboidal cube-like, columnar tall","distractors":["Squamous tall, cuboidal flat, columnar cube-like","Squamous cube-like, cuboidal tall, columnar flat","Squamous flat, cuboidal tall, columnar cube-like"],"meaning":"These shape terms describe individual cells. The names help describe different epithelial tissues.","source":"Day 3 Comprehensive Quiz Notes · p. 3"},
  {"id":"hca201a-day3-notes-tendons-versus-ligaments","scope":"day3","topic":"Cells, tissues & organs","term":"Tendons versus ligaments","prompt":"Which pairing correctly identifies two roles of connective tissue?","answer":"Tendon attaches muscle to bone. Ligament joins bone to bone.","distractors":["Tendon joins bone to bone. Ligament attaches muscle to bone.","Tendon attaches muscle to muscle. Ligament attaches muscle to bone.","Tendon joins bone to bone. Ligament attaches cartilage to muscle."],"meaning":"Both connect structures. Their typical attachment points distinguish them.","source":"Day 3 Comprehensive Quiz Notes · p. 3"},
  {"id":"hca201a-day3-notes-muscle-types-and-shivering","scope":"day3","topic":"Cells, tissues & organs","term":"Muscle types and shivering","prompt":"A client starts shivering while lying still. Which tissue produces those contractions?","answer":"Skeletal muscle activated involuntarily","distractors":["Smooth muscle activated voluntarily","Cardiac muscle moving the limbs","Skeletal muscle activated deliberately"],"meaning":"Shivering is an involuntary contraction of skeletal muscles, which generates heat.","source":"Day 3 Comprehensive Quiz Notes · p. 3"},
  {"id":"hca201a-day3-notes-four-tissues-in-skin","scope":"day3","topic":"Cells, tissues & organs","term":"Four tissues in skin","prompt":"Which mapping correctly connects all four basic tissue types to a role they can play in skin?","answer":"Epithelial barrier, connective support, smooth muscle movement, nervous sensation","distractors":["Epithelial support, connective sensation, smooth muscle barrier, nervous movement","Epithelial sensation, connective movement, smooth muscle support, nervous barrier","Epithelial movement, connective barrier, smooth muscle sensation, nervous support"],"meaning":"The outer barrier is epithelial. Connective tissue supports the skin, smooth muscle can raise hairs, and sensory nerves detect stimuli.","source":"Day 3 Comprehensive Quiz Notes · p. 3","reference":{"label":"OpenStax","url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues"}},
  {"id":"hca201a-day3-08-05","scope":"day3","topic":"Skin structure & function","term":"Subcutaneous attachment","prompt":"Which account best explains why the diagram depicts fatty tissue beneath the dermis separately?","answer":"It helps anchor and cushion the skin, insulates the body, and stores energy.","distractors":["It lines the outer surface and supplies the skin's melanin.","It contains the surface barrier cells that are shed during renewal.","It is the epithelial layer where surface blood vessels dilate."],"meaning":"The hypodermis is beneath the skin proper and provides cushioning, insulation, energy storage, and attachment.","source":"Day 3 Comprehensive Quiz Notes · p. 4"},
  {"id":"hca201a-day3-08-10","scope":"day3","topic":"Skin structure & function","term":"Sebaceous gland","prompt":"Which structure produces the secretion that softens and protects skin and hair?","answer":"Sebaceous gland","distractors":["Sweat gland","Hair shaft","Epidermal pigment layer"],"meaning":"Sebaceous glands produce sebum, an oily secretion. Sweat glands produce watery perspiration.","source":"Day 3 Comprehensive Quiz Notes · p. 5"},
  {"id":"hca201a-day3-09-03","scope":"day3","topic":"Skin structure & function","term":"Water retention","prompt":"Why does extensive loss of the skin barrier pose both a fluid and an infection concern?","answer":"More water can escape, and microorganisms can enter more easily.","distractors":["More water can escape, but microorganisms have the same access as before.","Microorganisms can enter more easily, but the barrier has no role in limiting water loss.","Water loss and microorganism entry depend primarily on the nerves below the damaged area."],"meaning":"The intact physical barrier limits both water loss and entry of microorganisms and harmful substances.","source":"Day 3 Comprehensive Quiz Notes · p. 5"},
  {"id":"hca201a-day3-notes-epidermal-nutrition","scope":"day3","topic":"Skin structure & function","term":"Epidermal nutrition","prompt":"An anatomy diagram shows no vessels in the outer epithelial layer. How does that layer receive oxygen and nutrients?","answer":"From vessels in the dermis beneath it","distractors":["From its own capillaries in deeper epidermal cells","From perspiration returning through the sweat ducts","From sebum released by nearby follicles"],"meaning":"The epidermis has no blood vessels of its own. Materials diffuse to it from the vascular dermis.","source":"Day 3 Comprehensive Quiz Notes · p. 4"},
  {"id":"hca201a-day3-notes-epidermal-renewal","scope":"day3","topic":"Skin structure & function","term":"Epidermal renewal","prompt":"Which sequence describes normal renewal of the epidermis?","answer":"Deeper cells divide, move outward, mature, die, and shed.","distractors":["Surface cells divide, move inward, and become dermal connective tissue.","Deeper cells divide, then enter sweat ducts to be shed.","Dermal cells become the outer epidermis by passing through blood vessels."],"meaning":"New epidermal cells form deeper in the layer and move toward the surface as they mature.","source":"Day 3 Comprehensive Quiz Notes · p. 4"},
  {"id":"hca201a-day3-notes-homeostatic-cooling","scope":"day3","topic":"Skin structure & function","term":"Homeostatic cooling","prompt":"Which skin responses work together during overheating?","answer":"Surface vasodilation and sweating","distractors":["Surface vasoconstriction and sweating","Surface vasodilation and shivering","Surface vasoconstriction and shivering"],"meaning":"Wider surface vessels promote heat loss. Sweat evaporation takes heat away from the body.","source":"Day 3 Comprehensive Quiz Notes · p. 4"},
  {"id":"hca201a-day3-notes-homeostatic-warming","scope":"day3","topic":"Skin structure & function","term":"Homeostatic warming","prompt":"Which combination conserves heat and also produces heat when a client becomes cold?","answer":"Surface vasoconstriction and shivering","distractors":["Surface vasodilation and shivering","Surface vasoconstriction and increased sweating","Surface vasodilation and increased sweating"],"meaning":"Narrowing superficial blood vessels limits heat loss. Shivering generates heat through muscle contractions.","source":"Day 3 Comprehensive Quiz Notes · p. 4"},
  {"id":"hca201a-day3-notes-sweat-and-elimination","scope":"day3","topic":"Skin structure & function","term":"Sweat and elimination","prompt":"Which observation illustrates both elimination and temperature regulation by the same secretion?","answer":"Perspiration carries small amounts of salts and urea, and its evaporation removes heat.","distractors":["Sebum carries urea to the surface, and its evaporation removes heat.","Perspiration removes heat mainly by conserving surface blood flow.","Skin cells shed salt, and hair follicles excrete most body waste."],"meaning":"Sweat contains water, salts, and small amounts of waste, including urea. Its evaporation cools the body.","source":"Day 3 Comprehensive Quiz Notes · p. 5"},
  {"id":"hca201a-day3-notes-nail-and-hair-functions","scope":"day3","topic":"Skin structure & function","term":"Nail and hair functions","prompt":"Which pairing identifies two protective roles of integumentary appendages?","answer":"Nails shield digit tips; hair can help keep foreign material out of sensitive areas.","distractors":["Nails shield digit tips; hair mainly regulates surface blood flow.","Hair helps keep foreign material out; nails primarily release sebum.","Nails release sweat; scalp hair is the main barrier limiting water loss."],"meaning":"Hard nail plates protect fingers and toes. Hair protects sensitive areas and scalp hair can help retain heat.","source":"Day 3 Comprehensive Quiz Notes · p. 5"},
  {"id":"hca201a-day3-notes-skin-and-nail-observations","scope":"day3","topic":"Skin structure & function","term":"Skin and nail observations","prompt":"During care the HCA notices newly grey-blue nail beds. Which response stays within the HCA role?","answer":"Promptly report the observed colour change and any other symptoms.","distractors":["Chart it as a confirmed circulation disorder before calling the nurse.","Report a chronic lung disease diagnosis if the client's nails are clubbed.","Record the change for a future review and wait for the client to report discomfort."],"meaning":"Skin or nail changes can be important observations, but they do not establish a diagnosis. Follow the workplace escalation protocol.","source":"Day 3 Comprehensive Quiz Notes · p. 5"},
  {"id":"hca201a-day3-notes-sensation-and-protection","scope":"day3","topic":"Skin structure & function","term":"Sensation and protection","prompt":"A client has reduced sensation in the feet. Why does that matter even if the skin has no visible breaks?","answer":"They may miss early warning sensations from pressure, temperature, or minor injury.","distractors":["Intact skin provides no defence against infection when sensation is reduced.","The upper skin layers immediately lose their source of blood vessels.","Reduced sensation causes the sweat glands to release sebum instead of perspiration."],"meaning":"Skin nerve endings detect touch, pain, pressure, and temperature. With reduced sensation, a client may not notice harmful pressure or heat.","source":"Day 3 Comprehensive Quiz Notes · p. 5"},
  {"id":"hca201a-day3-notes-anatomical-route-of-perspiration","scope":"day3","topic":"Skin structure & function","term":"Anatomical route of perspiration","prompt":"Which pathway connects the part of the skin that makes perspiration to where it leaves the body?","answer":"Sweat gland → sweat duct → opening at the skin surface","distractors":["Sebaceous gland → sweat duct → opening at the skin surface","Sweat gland → hair shaft → opening below the epidermis","Epidermal pigment cells → sweat duct → subcutaneous fat"],"meaning":"A sweat gland produces perspiration, which travels through a duct to a surface opening. Sebaceous glands make sebum.","source":"Day 3 Comprehensive Quiz Notes · p. 5"},
  {"id":"hca201a-day3-11-03","scope":"day3","topic":"Common skin conditions","term":"Shingles latency","prompt":"A client had chickenpox as a child and develops herpes zoster decades later. Which sequence explains the connection?","answer":"The virus stayed dormant in nerve tissue and later reactivated.","distractors":["The virus stayed dormant in hair follicles until the skin was irritated.","The virus caused a new acute chickenpox infection that later moved into a nerve.","Bacteria from the original lesions stayed dormant and later reinfected the skin."],"meaning":"Shingles is reactivation of varicella-zoster virus. It is a viral illness, and risk rises with older age and weakened immunity.","source":"Day 3 Comprehensive Quiz Notes · p. 7","reference":{"label":"Public Health Agency of Canada","url":"https://www.canada.ca/en/public-health/services/infectious-diseases/fact-sheet-shingles-herpes-zoster.html"}},
  {"id":"hca201a-day3-11-08","scope":"day3","topic":"Common skin conditions","term":"Shingles treatment categories","prompt":"Which pairing gives the purpose of two clinician-directed medication categories used for shingles?","answer":"Antiviral treatment can shorten the illness. Analgesia addresses pain.","distractors":["Antiviral treatment addresses pain only. Analgesia prevents viral replication.","Antiviral treatment is used to manage bacterial crusting. Analgesia lowers the chance of transmission.","Antiviral treatment prevents every recurrence. Analgesia prevents blisters from forming."],"meaning":"Antivirals can reduce duration and severity. Pain-relief medication treats discomfort, while vaccination is used for prevention.","source":"Day 3 Comprehensive Quiz Notes · p. 7","reference":{"label":"Public Health Agency of Canada","url":"https://www.canada.ca/en/public-health/services/infectious-diseases/fact-sheet-shingles-herpes-zoster.html"}},
  {"id":"hca201a-day3-12-02","scope":"day3","topic":"Common skin conditions","term":"Wheals","prompt":"In a circular, raised, spongy lesion with a surrounding red area, which part is the wheal and which is the flare?","answer":"The raised centre is the wheal. Surrounding redness is the flare.","distractors":["The raised centre is the flare. Surrounding redness is the wheal.","The raised centre is a vesicle. Surrounding redness is the wheal.","The raised centre is a plaque. Surrounding redness is a vesicle."],"meaning":"A wheal is the raised area. A flare is the redness around it.","source":"Day 3 Comprehensive Quiz Notes · p. 7"},
  {"id":"hca201a-day3-13-01","scope":"day3","topic":"Common skin conditions","term":"Contact dermatitis","prompt":"One client reacts to a detergent that directly damages skin. Another reacts to latex after becoming sensitized. Which pairing is correct?","answer":"Irritant contact dermatitis, then allergic contact dermatitis","distractors":["Allergic contact dermatitis, then irritant contact dermatitis","Atopic eczema, then irritant contact dermatitis","Irritant contact dermatitis, then bacterial folliculitis"],"meaning":"Irritants directly damage or inflame skin. Allergic contact dermatitis follows an immune reaction after sensitization.","source":"Day 3 Comprehensive Quiz Notes · p. 7"},
  {"id":"hca201a-day3-14-03","scope":"day3","topic":"Common skin conditions","term":"Eczema features","prompt":"Two clients report itching. Which pattern more strongly supports eczema over transient hives?","answer":"Dry patches persist in the folds, with scratch damage.","distractors":["Raised wheals change shape over the next hour.","A single follicular lump develops a purulent centre.","An oily surface growth catches on a sleeve."],"meaning":"Eczema often appears as dry, inflamed, itchy patches. Its appearance varies and scratching may injure the skin barrier.","source":"Day 3 Comprehensive Quiz Notes · p. 8"},
  {"id":"hca201a-day3-15-02","scope":"day3","topic":"Common skin conditions","term":"Scabies itch","prompt":"Two clients have itching. Which explanation links scabies with its characteristic mechanism?","answer":"The skin reacts to mite material after mites burrow and lay eggs.","distractors":["The itching comes from shingles virus reactivating in the hair shaft.","The itching results from bacteria growing deep inside one hair follicle.","The itching results from skin cells piling up to form scaly plaques."],"meaning":"Scabies mites burrow in superficial skin. A reaction to the mites and their eggs or waste produces itching.","source":"Day 3 Comprehensive Quiz Notes · p. 8"},
  {"id":"hca201a-day3-15-04","scope":"day3","topic":"Common skin conditions","term":"Scabies before diagnosis","prompt":"A resident had close skin contact with another resident weeks before itching began. Why does the timing still matter for a scabies investigation?","answer":"Close skin contact can spread scabies during the symptom-free period.","distractors":["A resident is contagious only after a rash has been formally diagnosed.","Symptoms appearing weeks later point away from contact transmission.","Scabies spreads before itching only if a burrow was visible at the time."],"meaning":"Symptoms after a first infestation can take several weeks to appear. Spread can occur during that interval.","source":"Day 3 Comprehensive Quiz Notes · p. 8","reference":{"label":"CDC","url":"https://www.cdc.gov/scabies/about/"}},
  {"id":"hca201a-day3-16-01","scope":"day3","topic":"Common skin conditions","term":"Psoriasis appearance and course","prompt":"Which pattern is more consistent with psoriasis than with urticaria or impetigo?","answer":"Persistent, thickened plaques with a silvery scale","distractors":["Soft raised wheals that change size within hours","Oozing lesions that dry into yellow crusts","Small scattered fluid-filled lesions in a painful one-sided band"],"meaning":"Psoriasis can cause chronic, inflamed, scaly plaques. Skin cells accumulate faster than they are shed.","source":"Day 3 Comprehensive Quiz Notes · p. 8"},
  {"id":"hca201a-day3-17-02","scope":"day3","topic":"Common skin conditions","term":"Boil cause","prompt":"Which description connects a furuncle's appearance to its underlying cause?","answer":"A tender pus-filled lump can result from a bacterial infection in a hair follicle.","distractors":["A tender pus-filled lump forms when an oil gland produces protective sebum.","A scaly patch forms when bacteria are trapped inside a sealed cyst wall.","A patch of shifting wheals forms when Staphylococcus infects a hair shaft."],"meaning":"A boil is a furuncle, commonly caused by Staphylococcus in a follicle. The skin may show a white or yellow point before drainage. Typical sites include the back, shoulders, underarms, thighs, and buttocks.","source":"Day 3 Comprehensive Quiz Notes · p. 8"},
  {"id":"hca201a-day3-18-03","scope":"day3","topic":"Common skin conditions","term":"Cyst wall","prompt":"What structural distinction helps separate a cyst from a boil in the notes?","answer":"A cyst is a closed, walled sac. A boil is an infected hair follicle.","distractors":["Both are infected follicles, but a cyst always contains air.","Both are closed sacs, but only a boil has a wall.","A cyst is a surface plaque. A boil is a permanent sac beneath it."],"meaning":"A cyst has a distinct membrane and can contain air, fluid, or semi-solid material. A boil is a follicle infection.","source":"Day 3 Comprehensive Quiz Notes · p. 9"},
  {"id":"hca201a-day3-18-04","scope":"day3","topic":"Common skin conditions","term":"Cyst persistence and treatment","prompt":"Which statement best describes whether cysts persist or need removal?","answer":"It depends on the type. Some persist, while others can resolve on their own.","distractors":["Every cyst needs surgery to resolve.","Every cyst disappears within a few days.","Medication is necessary for every cyst."],"meaning":"The slide emphasizes persistence and treatment. Some cysts, including some ganglion cysts, may resolve without treatment. The notes illustrate a ganglion cyst near a hand joint. Treatment depends on the type and symptoms.","source":"Day 3 PowerPoint · slide 18","reference":{"label":"NHS","url":"https://www.nhs.uk/conditions/ganglion-cyst/"}},
  {"id":"hca201a-day3-19-01","scope":"day3","topic":"Common skin conditions","term":"Impetigo cause","prompt":"Which explanation links a scrape to the development of contagious impetigo?","answer":"Staph or strep bacteria can enter through the skin break.","distractors":["Varicella-zoster reactivates whenever a cut reaches the epidermis.","A fungal infection of a hair shaft forms after every scrape.","A sensitized immune response always produces contagious crusting."],"meaning":"A cut, scratch, or other disruption of the skin barrier can allow staph or strep to enter.","source":"Day 3 Comprehensive Quiz Notes · p. 9"},
  {"id":"hca201a-day3-19-03","scope":"day3","topic":"Common skin conditions","term":"Self-spread of impetigo","prompt":"A client scratches a draining impetigo lesion and then rubs unaffected skin. Which mechanism explains how a new lesion could develop?","answer":"The hands can carry bacteria from drainage to another part of the body.","distractors":["The new lesion develops because the original crust changes colour.","Rubbing causes bacterial spread through an intact hair shaft without contact with the lesion.","The new lesion represents dormant virus reactivating in the same nerve pathway."],"meaning":"Touching infected lesions or their drainage can transfer bacteria. Follow the plan and support hand hygiene.","source":"Day 3 Comprehensive Quiz Notes · p. 9"},
  {"id":"hca201a-day3-notes-shingles-rash-pattern","scope":"day3","topic":"Common skin conditions","term":"Shingles rash pattern","prompt":"Which report most closely matches the shingles presentation discussed in the notes?","answer":"Burning pain followed by a one-sided band of raised, fluid-filled blisters","distractors":["Round, raised areas that change shape over an hour after a new food","Itchy, scaly patches in both elbow creases","A single painful, pus-filled lump centred on a hair"],"meaning":"Pain, itching, burning, or tingling can precede a blistering rash that often follows a one-sided nerve distribution. Common sites include the trunk, buttocks, and face.","source":"Day 3 Comprehensive Quiz Notes · p. 7","reference":{"label":"HealthLink BC","url":"https://www.healthlinkbc.ca/healthwise/shingles"}},
  {"id":"hca201a-day3-notes-shingles-pain-after-healing","scope":"day3","topic":"Common skin conditions","term":"Shingles pain after healing","prompt":"A client reports burning pain where a shingles rash has already healed. Which explanation is consistent with the notes?","answer":"Nerve pain can persist after the visible lesions heal.","distractors":["Persistent pain implies the blisters have begun draining again.","Pain after healing indicates a new bacterial follicle infection.","Shingles-related pain resolves as soon as the last blister crusts."],"meaning":"Postherpetic neuralgia is persistent nerve pain after shingles. It can last for months or longer.","source":"Day 3 Comprehensive Quiz Notes · p. 7","reference":{"label":"HealthLink BC","url":"https://www.healthlinkbc.ca/healthwise/shingles"}},
  {"id":"hca201a-day3-notes-shingles-exposure-outcome","scope":"day3","topic":"Common skin conditions","term":"Shingles exposure outcome","prompt":"A person without immunity has contact with active shingles lesions and acquires varicella-zoster virus. What illness can develop from this exposure?","answer":"Chickenpox","distractors":["A new episode of shingles caused directly by exposure","Impetigo from the varicella-zoster virus","Scabies following viral latency"],"meaning":"A susceptible person can develop chickenpox. Shingles occurs later through reactivation of a virus already in the body.","source":"Day 3 Comprehensive Quiz Notes · p. 7","reference":{"label":"HealthLink BC","url":"https://www.healthlinkbc.ca/healthwise/shingles"}},
  {"id":"hca201a-day3-notes-shingles-near-the-eye","scope":"day3","topic":"Common skin conditions","term":"Shingles near the eye","prompt":"A client reports new burning and blisters near one eye. Which response best fits the HCA role?","answer":"Escalate promptly for assessment and follow infection-control directions.","distractors":["Wait for the rash to spread before deciding whether to report.","Record it at the end of the shift if the client has no fever.","Ask whether the client had chickenpox, then report only if they say yes."],"meaning":"A rash near the eye needs prompt assessment because eye involvement can damage vision.","source":"Day 3 Comprehensive Quiz Notes · p. 7","reference":{"label":"HealthLink BC","url":"https://www.healthlinkbc.ca/healthwise/shingles"}},
  {"id":"hca201a-day3-notes-urticaria-evolution","scope":"day3","topic":"Common skin conditions","term":"Urticaria evolution","prompt":"Which change over time most strongly fits the urticaria pattern described in class?","answer":"Itchy raised welts alter shape or size over minutes to hours.","distractors":["A scaly plaque gradually thickens in the same place over weeks.","A tender follicular lump develops a white head over several days.","A shallow sore oozes and develops crust over time."],"meaning":"Urticarial wheals change quickly and vary in size. Their shifting shape helps distinguish them from more persistent lesions.","source":"Day 3 Comprehensive Quiz Notes · p. 7"},
  {"id":"hca201a-day3-notes-urticaria-observations","scope":"day3","topic":"Common skin conditions","term":"Urticaria observations","prompt":"Raised itchy areas appear after a meal and a newly applied cream. Which report is most useful?","answer":"Describe when the raised areas appeared and changed, and note both possible exposures.","distractors":["Record the meal as the confirmed cause and omit the cream.","Record the product names while leaving out the appearance and timing.","Wait to report until the wheals stop changing shape."],"meaning":"Record the timeline, appearance, client symptoms, and possible exposures. Several exposures can cause hives and a temporal link alone does not establish the trigger.","source":"Day 3 Comprehensive Quiz Notes · p. 7"},
  {"id":"hca201a-day3-notes-urticaria-emergency-escalation","scope":"day3","topic":"Common skin conditions","term":"Urticaria emergency escalation","prompt":"Raised itchy wheals are followed by tongue swelling and breathing difficulty. What should the HCA do first?","answer":"Activate the workplace emergency response immediately.","distractors":["Document the size of the wheals before contacting the team.","Get an antihistamine for the client, then reassess before escalating.","Call the routine reporting line and wait for a return call."],"meaning":"Breathing difficulty or swelling of the tongue or throat can indicate a severe allergic reaction. Activate emergency help per protocol.","source":"Day 3 Comprehensive Quiz Notes · p. 7","reference":{"label":"Emergency Care BC","url":"https://emergencycarebc.ca/wp-content/uploads/2024/09/Allergic-Reaction.pdf"}},
  {"id":"hca201a-day3-notes-contact-dermatitis-care","scope":"day3","topic":"Common skin conditions","term":"Contact dermatitis care","prompt":"Warm, tender redness appears under a newly used product and starts spreading. What is the appropriate HCA action?","answer":"Report the spread and follow the approved plan to avoid further exposure.","distractors":["Test the same product on a second patch of skin for comparison.","Substitute an over-the-counter product while the client waits for assessment.","Document an allergy as confirmed because the rash matches the contact area."],"meaning":"Record the location and exposure and report worsening. Product substitutions and a diagnosis are clinical decisions.","source":"Day 3 Comprehensive Quiz Notes · p. 7"},
  {"id":"hca201a-day3-notes-papules-versus-vesicles","scope":"day3","topic":"Common skin conditions","term":"Papules versus vesicles","prompt":"The HCA observes small solid bumps and nearby small fluid-filled bumps. Which chart terms distinguish them?","answer":"Papules for the solid bumps, vesicles for the fluid-filled bumps","distractors":["Vesicles for the solid bumps, papules for the fluid-filled bumps","Papules for the solid bumps, plaques for the fluid-filled bumps","Wheals for the solid bumps, papules for the fluid-filled bumps"],"meaning":"Papules are small solid raised lesions. Vesicles contain fluid.","source":"Day 3 Comprehensive Quiz Notes · p. 8"},
  {"id":"hca201a-day3-notes-eczema-skin-barrier-support","scope":"day3","topic":"Common skin conditions","term":"Eczema skin barrier support","prompt":"A client with eczema has new scratch marks and asks the HCA to try a fragranced lotion from home. What response best supports safe care?","answer":"Report the new breaks and use only products authorized in the care plan.","distractors":["Try a small amount first, then report if the redness gets worse.","Apply the home lotion over the breaks and document the request afterward.","Skip reporting skin breaks unless there is drainage or fever."],"meaning":"Scratching can worsen skin-barrier damage. Support comfort with approved care and report new breaks.","source":"Day 3 Comprehensive Quiz Notes · p. 8"},
  {"id":"hca201a-day3-notes-scabies-assignment-and-laundering","scope":"day3","topic":"Common skin conditions","term":"Scabies assignment and laundering","prompt":"Scabies has been reported on the unit. What should the HCA do when assigned to handle the client's bedding?","answer":"Follow assigned contact precautions and the facility's handling and laundering directions.","distractors":["Shake out loose material before bagging the bedding in the hallway.","Use the usual shared linen route and add precautions only if itching is visible.","Set the facility's laundering schedule based on the textbook interval."],"meaning":"The infection-control plan determines contact precautions, PPE, and handling of linens. Follow local procedure and assigned duties.","source":"Day 3 Comprehensive Quiz Notes · p. 8","reference":{"label":"CDC","url":"https://www.cdc.gov/scabies/php/public-health-strategy/index.html"}},
  {"id":"hca201a-day3-notes-scabies-repeat-treatment","scope":"day3","topic":"Common skin conditions","term":"Scabies repeat treatment","prompt":"A client asks why a repeat application appears on the scabies treatment plan. Which general explanation fits the notes?","answer":"Some regimens require a second application to address mites remaining or hatching after the first.","distractors":["The repeat dose is used only to confirm that the diagnosis was correct.","The first application cannot kill any mites and is used only to soothe the skin.","A second treatment is never needed if itching improves after the first."],"meaning":"Some clinician-directed regimens require a repeat application. Timing depends on the prescribed treatment.","source":"Day 3 Comprehensive Quiz Notes · p. 8","reference":{"label":"CDC","url":"https://www.cdc.gov/scabies/hcp/clinical-care/"}},
  {"id":"hca201a-day3-notes-psoriasis-and-client-dignity","scope":"day3","topic":"Common skin conditions","term":"Psoriasis and client dignity","prompt":"A client fears others will catch their psoriasis and avoids a group activity. Which response best supports care?","answer":"Acknowledge the concern, explain psoriasis is not contagious, and offer help with comfort or privacy.","distractors":["Suggest avoiding the activity until all plaques clear.","Ask the client to show the group the plaques so others understand.","Use the scabies contact-precaution plan whenever plaques are visible."],"meaning":"Psoriasis is not contagious. Visible plaques may still affect comfort, confidence, and participation. Plaques can occur in many locations. The immune system and genetics can contribute, and triggers vary.","source":"Day 3 Comprehensive Quiz Notes · p. 8"},
  {"id":"hca201a-day3-notes-boil-drainage-response","scope":"day3","topic":"Common skin conditions","term":"Boil drainage response","prompt":"A boil starts draining during personal care. Which response best fits the care plan and HCA role?","answer":"Use indicated PPE and hand hygiene, avoid squeezing, and report the drainage.","distractors":["Use a warm compress and then express the remaining drainage.","Apply a warm compress and use pressure to finish draining it.","Collect a swab and decide whether to start an antiseptic."],"meaning":"Drainage can happen unexpectedly. Use Standard Practices, report it, and perform only the care assigned.","source":"Day 3 Comprehensive Quiz Notes · p. 8"},
  {"id":"hca201a-day3-notes-cyst-observation-and-scope","scope":"day3","topic":"Common skin conditions","term":"Cyst observation and scope","prompt":"A previously charted lump appears larger and tender. What should the HCA do?","answer":"Describe the change in size and tenderness and report it for assessment.","distractors":["Try to empty the lump with a clean needle before reporting.","Ask the client to press on it to identify its contents.","Document a confirmed cyst type from its appearance alone."],"meaning":"Report changes in size, colour, tenderness, or drainage. Opening or treating a lump requires clinical assessment and direction.","source":"Day 3 Comprehensive Quiz Notes · p. 9"},
  {"id":"hca201a-day3-notes-impetigo-treatment-context","scope":"day3","topic":"Common skin conditions","term":"Impetigo treatment context","prompt":"Why might the treatment plan differ for a small affected area and widespread impetigo?","answer":"A clinician may use a topical antibiotic for limited disease and an oral antibiotic for more extensive disease.","distractors":["Limited disease usually requires an oral antiviral, while extensive disease uses only moisturizers.","Limited disease uses topical antifungal medication, while extensive disease uses only a warm compress.","The treatment route depends solely on whether the crust is yellow or grey."],"meaning":"Extent may affect the clinician's treatment choice. The HCA observes and supports assigned care. Lesions can ooze and form a yellow or grey crust.","source":"Day 3 Comprehensive Quiz Notes · p. 9","reference":{"label":"HealthLink BC","url":"https://www.healthlinkbc.ca/healthlinkbc-files/impetigo"}},
  {"id":"hca201a-day3-notes-contagious-versus-inflammatory-patterns","scope":"day3","topic":"Common skin conditions","term":"Contagious versus inflammatory patterns","prompt":"Which comparison correctly distinguishes two conditions that can spread between people from two that do not?","answer":"Scabies and impetigo can spread. Eczema and psoriasis are not contagious.","distractors":["Eczema and psoriasis can spread. Scabies and impetigo are not contagious.","Psoriasis and scabies can spread. Eczema and impetigo are not contagious.","Impetigo and eczema can spread. Psoriasis and scabies are not contagious."],"meaning":"Scabies is a mite infestation and impetigo is bacterial. Eczema and psoriasis are inflammatory conditions and do not pass from person to person.","source":"Day 3 Comprehensive Quiz Notes · p. 11"},
  {"id":"hca201a-day3-21-01","scope":"day3","topic":"Cancer, risk & detection","term":"Local invasion","prompt":"A tumour has grown into adjacent tissue and damaged it. Another tumour is large but remains localized without invasion. What distinction does this illustrate?","answer":"Invasion suggests malignancy. A large growth can still be benign.","distractors":["Size is the defining feature. The larger tumour must be malignant.","Local invasion and distant metastasis are the same process.","A tumour is benign as long as no distant spread has been detected."],"meaning":"Malignancy can involve invasion of nearby tissue even without known distant spread. Benign growths can still press on nearby structures.","source":"Day 3 Comprehensive Quiz Notes · p. 6"},
  {"id":"hca201a-day3-21-04","scope":"day3","topic":"Cancer, risk & detection","term":"Malignant recurrence","prompt":"After a tumour is removed, cancer of the same type grows again at the original site. How does this differ from a new growth in a distant organ?","answer":"Growth at the original site is a local recurrence. Distant growth from the original cancer is metastasis.","distractors":["Both are distant metastases regardless of where they grow.","Growth at the original site is metastasis, while distant growth is local recurrence.","Distant growth from the original cancer is classified as a new cancer type."],"meaning":"Some malignancies recur even after the original tumour has been removed.","source":"Day 3 PowerPoint · slide 21"},
  {"id":"hca201a-day3-22-03","scope":"day3","topic":"Cancer, risk & detection","term":"Secondary tumour growth","prompt":"A new liver tumour is made of cells from a client's previous colon cancer. How should this be described?","answer":"Metastatic colon cancer in the liver","distractors":["A separate primary liver cancer","Local recurrence at the original colon site","A benign tumour containing normal liver cells"],"meaning":"Cancer cells can leave a primary tumour, travel through blood or lymph, and grow at a distant site. The new growth retains the original cancer's identity.","source":"Day 3 Comprehensive Quiz Notes · p. 6"},
  {"id":"hca201a-day3-24-01","scope":"day3","topic":"Cancer, risk & detection","term":"Cancer causes and risks","prompt":"Which statement best distinguishes a risk factor from a diagnosis or a proven cause in a particular client?","answer":"Tobacco, alcohol, some infections, UV exposure, and family history can affect risk without proving an individual cause.","distractors":["A family history confirms that the client has inherited cancer.","A UV exposure history establishes the cause of every new skin lesion.","Without smoking, alcohol use, or a family history, cancer can be ruled out."],"meaning":"Cancer can arise from many factors. Diet, certain chemicals, hormones, viruses, and other exposures can also affect the risk of particular cancers. The PowerPoint includes a high-fat, high-calorie, low-fibre diet among the dietary patterns discussed.","source":"Day 3 PowerPoint · slide 24"},
  {"id":"hca201a-day3-25-05","scope":"day3","topic":"Cancer, risk & detection","term":"ABCDE diameter","prompt":"A 4 mm mole has grown and changed colour. How should the diameter clue be used?","answer":"Report the changes. A lesion can be concerning even below 6 mm.","distractors":["The diameter rules out concern until it is over 6 mm.","The 6 mm clue is based on how much the mole changed rather than its overall width.","Report only if the current measurement is at least 6 mm and the borders are jagged."],"meaning":"Diameter around 6 mm is one warning clue. Evolution can be significant in a smaller lesion.","source":"Day 3 Comprehensive Quiz Notes · p. 6","reference":{"label":"Canadian Cancer Society","url":"https://cancer.ca/en/cancer-information/cancer-types/melanoma-skin/signs-and-symptoms"}},
  {"id":"hca201a-day3-25-06","scope":"day3","topic":"Cancer, risk & detection","term":"ABCDE evolution","prompt":"A mole's size seems unchanged, but the client reports new itching and the HCA observes bleeding. What should be documented and reported?","answer":"New symptoms and bleeding are changes worth reporting even without a size change.","distractors":["Evolution only applies if the diameter has increased.","Use the history to chart the lesion as melanoma.","Record the size alone because bleeding is outside the observation checklist."],"meaning":"Evolution includes changes beyond size, such as colour, shape, texture, or new symptoms. Report findings without diagnosing.","source":"Day 3 Comprehensive Quiz Notes · p. 6","reference":{"label":"Canadian Cancer Society","url":"https://cancer.ca/en/cancer-information/cancer-types/melanoma-skin/signs-and-symptoms"}},
  {"id":"hca201a-day3-notes-carcinoma-tissue-of-origin","scope":"day3","topic":"Cancer, risk & detection","term":"Carcinoma tissue of origin","prompt":"A pathology report describes a carcinoma. What does the term tell you about where it arose?","answer":"It arose in epithelial tissue.","distractors":["It arose from connective tissue.","It arose from muscle tissue.","It arose from nervous tissue."],"meaning":"A carcinoma arises from epithelium. Basal cell and squamous cell skin cancers are both carcinomas.","source":"Day 3 Comprehensive Quiz Notes · p. 6"},
  {"id":"hca201a-day3-notes-basal-cell-versus-squamous-cell-pattern","scope":"day3","topic":"Cancer, risk & detection","term":"Basal cell versus squamous cell pattern","prompt":"Which pairing best matches typical appearances from the notes?","answer":"Basal cell can look pearly; squamous cell can look thickened and scaly.","distractors":["Basal cell usually looks like shifting wheals; squamous cell usually follows a one-sided nerve.","Basal cell usually follows a nerve; squamous cell usually looks like a closed cyst.","Basal cell typically looks like a fluid-filled vesicle; squamous cell typically looks like shifting wheals."],"meaning":"A pearly bump or nonhealing sore may occur with basal cell carcinoma. A persistent thick or scaly lesion can occur with squamous cell carcinoma. Appearances can overlap.","source":"Day 3 Comprehensive Quiz Notes · p. 6","reference":{"label":"Canadian Cancer Society","url":"https://cancer.ca/en/cancer-information/cancer-types/skin-non-melanoma/signs-and-symptoms"}},
  {"id":"hca201a-day3-notes-skin-cancer-and-spread","scope":"day3","topic":"Cancer, risk & detection","term":"Skin cancer and spread","prompt":"Which statement compares the spread of basal cell carcinoma, squamous cell carcinoma, and melanoma?","answer":"Basal cell rarely spreads, squamous cell can spread, and melanoma is particularly dangerous because it can metastasize.","distractors":["Basal and squamous cell both commonly spread while melanoma rarely spreads.","Basal cell spreads most readily, and squamous cell and melanoma remain confined to the epidermis.","Melanoma tends to remain local until it reaches a diameter of 6 mm."],"meaning":"The main study distinction is the particularly serious potential for melanoma to spread. Squamous cell can metastasize and basal cell rarely does.","source":"Day 3 Comprehensive Quiz Notes · p. 6"},
  {"id":"hca201a-day3-notes-melanoma-risk-exposures","scope":"day3","topic":"Cancer, risk & detection","term":"Melanoma risk exposures","prompt":"Which history combines exposures that can raise melanoma risk?","answer":"Repeated sunburns and use of UV tanning beds","distractors":["Repeated sunburns and family history of eczema as equivalent risk factors","Outdoor work and limited time outside as equivalent UV exposures","Frequent sweating and use of moisturizers as UV-related risks"],"meaning":"UV exposure from the sun and tanning beds increases skin cancer risk. Repeated sunburns are particularly relevant to melanoma risk.","source":"Day 3 Comprehensive Quiz Notes · p. 6"},
  {"id":"hca201a-day3-notes-abcde-description-matching","scope":"day3","topic":"Cancer, risk & detection","term":"ABCDE description matching","prompt":"A mole has two unequal halves, a jagged outline, and uneven brown and black areas. Which indicators do these correspond to, in order?","answer":"Asymmetry, border, colour","distractors":["Border, asymmetry, evolution","Asymmetry, diameter, colour","Colour, border, evolution"],"meaning":"A compares the halves, B describes the edges, and C describes unequal shades or multiple colours.","source":"Day 3 Comprehensive Quiz Notes · p. 6","reference":{"label":"Canadian Cancer Society","url":"https://cancer.ca/en/cancer-information/cancer-types/melanoma-skin/signs-and-symptoms"}},
  {"id":"hca201a-day3-notes-sun-protection-beyond-sunscreen","scope":"day3","topic":"Cancer, risk & detection","term":"Sun protection beyond sunscreen","prompt":"A client asks how the class notes' SPF 15 example compares with current Canadian Cancer Society guidance. Which advice is current?","answer":"Use broad-spectrum SPF 30 or higher alongside shade and protective clothing.","distractors":["Use SPF 15 as the current first choice and stay in direct sun for longer.","Use SPF 30 only on cloudy days and omit protective clothing in direct sun.","Use sunscreen only after the skin shows early signs of a burn."],"meaning":"The notes quote an older threshold. Current Canadian Cancer Society guidance recommends broad-spectrum SPF 30 or higher for exposed areas alongside other sun protection. UV protection reduces risk. Early detection and prompt assessment help find existing skin cancers sooner.","source":"Day 3 Comprehensive Quiz Notes · p. 7","reference":{"label":"Canadian Cancer Society","url":"https://cancer.ca/en/cancer-information/reduce-your-risk/be-sun-safe/enjoy-the-sun-safely"}},
  {"id":"hca201a-day3-notes-skin-cancer-treatment-terms","scope":"day3","topic":"Cancer, risk & detection","term":"Skin cancer treatment terms","prompt":"A clinician describes clear margins and mentions cryotherapy as another option for a different lesion. Which interpretation fits?","answer":"Clear margins mean no cancer cells at the edge of removed tissue. Cryotherapy uses freezing.","distractors":["Clear margins mean the lesion has even borders. Cryotherapy uses heat.","Clear margins mean the lesion has not changed colour. Cryotherapy uses radiation.","Clear margins mean the lesion is under 6 mm. Cryotherapy uses an oral medicine."],"meaning":"Clear margins are assessed on excised tissue. Clinicians select treatment based on the lesion and can use freezing for selected lesions.","source":"Day 3 Comprehensive Quiz Notes · p. 7","reference":{"label":"Canadian Cancer Society","url":"https://cancer.ca/en/cancer-information/cancer-types/skin-non-melanoma/treatment/surgery"}},
  {"id":"hca201a-day3-notes-nonhealing-lesion-report","scope":"day3","topic":"Cancer, risk & detection","term":"Nonhealing lesion report","prompt":"During grooming, the HCA notices a pearly bump that has bled and crusted repeatedly. What should be communicated?","answer":"Describe the site, size, bleeding, and timeline and report the nonhealing change.","distractors":["Tell the client the pearly appearance confirms basal cell carcinoma.","Wait until the bump crosses the ABCDE diameter threshold.","Report only the colour because the crust makes other findings unreliable."],"meaning":"A repeatedly bleeding or nonhealing skin change deserves assessment. Typical patterns guide observation and reporting rather than diagnosis.","source":"Day 3 Comprehensive Quiz Notes · p. 6"},
  {"id":"hca201a-day3-26-03","scope":"day3","topic":"Cancer treatment","term":"Tumour site","prompt":"Two clients have the same type of cancer but different treatment plans. Which clinical factors best explain why?","answer":"Tumour location, size, and extent of spread can change what is appropriate.","distractors":["A shared tumour type means both must receive the same first treatment.","Tumour size matters, but location and spread make no difference.","If cancer is detected early, tumour type and location are no longer used in planning."],"meaning":"The team considers tumour type, site, size, and spread. Earlier detection may improve available choices, but treatment is individualized.","source":"Day 3 PowerPoint · slide 26"},
  {"id":"hca201a-day3-26-06","scope":"day3","topic":"Cancer treatment","term":"Cure as a goal","prompt":"One plan aims to eliminate the cancer, another to slow progression, and a third to reduce symptoms. Which goals do these represent, in order?","answer":"Cure, disease control, symptom relief","distractors":["Disease control, cure, symptom relief","Cure, symptom relief, disease control","Symptom relief, disease control, cure"],"meaning":"A plan can aim to eliminate cancer, control its progression, or improve comfort. A treatment may serve more than one purpose.","source":"Day 3 PowerPoint · slide 26"},
  {"id":"hca201a-day3-27-04","scope":"day3","topic":"Cancer treatment","term":"Surgery and advanced cancer pain","prompt":"A cancer is unlikely to be cured, but the team discusses surgery or radiation to relieve pressure from a tumour. How should the intent be understood?","answer":"Either approach can be used to relieve symptoms depending on the tumour and care plan.","distractors":["Surgery can be offered only when complete cure is the aim.","Radiation can reduce pressure only after all tumour tissue has been removed.","Reducing pressure is a screening goal rather than a treatment goal."],"meaning":"Removing or shrinking tumour tissue can relieve pressure and pain. Treatment goals depend on the individual situation.","source":"Day 3 PowerPoint · slide 27"},
  {"id":"hca201a-day3-27-06","scope":"day3","topic":"Cancer treatment","term":"Preoperative radiation","prompt":"A team discusses preoperative radiation or preoperative chemotherapy. What goal can either approach share?","answer":"Shrinking the tumour before surgery","distractors":["Confirming clear surgical margins after surgery","Removing the tumour with instruments during the treatment session","Treating radiation effects after surgery"],"meaning":"Either treatment may be used before surgery to shrink a tumour, depending on cancer type and treatment plan.","source":"Day 3 PowerPoint · slides 27–28"},
  {"id":"hca201a-day3-27-07","scope":"day3","topic":"Cancer treatment","term":"Postoperative radiation","prompt":"A tumour has been removed and the team recommends radiation to the surgical area. What is the likely intention?","answer":"Target possible remaining cancer cells near the surgical site.","distractors":["Reach circulating cancer cells throughout the body in the same way as systemic chemotherapy.","Remove the surgical specimen so its margins can be examined.","Shrink the already removed tumour before the operation."],"meaning":"Radiation can act on the area treated, including residual local cells after surgery.","source":"Day 3 PowerPoint · slide 27"},
  {"id":"hca201a-day3-28-03","scope":"day3","topic":"Cancer treatment","term":"Chemotherapy and dispersed cells","prompt":"Why might systemic chemotherapy be used in addition to treating a tumour locally?","answer":"Drug treatment can reach cancer cells beyond the original site.","distractors":["Systemic chemotherapy only acts in the surgical bed.","Systemic chemotherapy removes tissue while a pathologist checks the edges.","Systemic chemotherapy blocks hormone production in every cancer type."],"meaning":"Systemic chemotherapy reaches multiple body areas. It may kill cancer cells that have spread and can also affect healthy fast-growing cells.","source":"Day 3 PowerPoint · slide 28"},
  {"id":"hca201a-day3-28-05","scope":"day3","topic":"Cancer treatment","term":"Hormone therapy mechanism","prompt":"What do a hormone-blocking drug and removal of a relevant hormone-producing gland have in common?","answer":"Both can reduce a hormone-dependent cancer's access to growth signals.","distractors":["Both directly cut out the primary tumour during treatment.","Both stimulate cancer-directed immune cells as their main mechanism.","Both act by targeting radiation at the hormone-producing gland."],"meaning":"Hormone therapy can reduce production or block use of a hormone that supports certain cancers.","source":"Day 3 PowerPoint · slide 28"},
  {"id":"hca201a-day3-29-02","scope":"day3","topic":"Cancer treatment","term":"Immunotherapy and side effects","prompt":"A client assumes immunotherapy prevents the side effects of all their other treatments. Which explanation is accurate?","answer":"It helps the immune system act against cancer and can cause effects in healthy tissue too.","distractors":["It works by protecting healthy tissue from every other treatment.","It acts only inside the tumour, so effects elsewhere are unrelated.","Its only role is to reduce pain from surgery or radiation."],"meaning":"Immunotherapy changes the immune response against cancer. Some immune effects can harm healthy tissue and require assessment.","source":"Day 3 PowerPoint · slide 29","reference":{"label":"National Cancer Institute","url":"https://www.cancer.gov/about-cancer/treatment/types/immunotherapy/side-effects"}},
  {"id":"hca201a-day3-30-06","scope":"day3","topic":"Supporting clients with cancer","term":"Treatment side effects","prompt":"A client reports new nausea after treatment. Which information best helps the care team evaluate it?","answer":"When it started, any effects on food or fluid intake, and what the client reports or the HCA observes","distractors":["The HCA's diagnosis and choice of an anti-nausea product","Only the treatment date, because current symptoms may be subjective","Only whether another client had the same symptom"],"meaning":"Treatment effects vary. Describe the symptom and its impact and follow the plan for reporting rather than attributing it independently.","source":"Day 3 PowerPoint · slides 27, 30"},
  {"id":"hca201a-day3-notes-cancer-care-competing-needs","scope":"day3","topic":"Supporting clients with cancer","term":"Cancer care competing needs","prompt":"A client in cancer care has reduced intake, constipation, and decreased mobility. What is the most useful HCA handover?","answer":"Report intake, bowel changes, and mobility alongside relevant symptoms and skin observations.","distractors":["Report intake only, since bowel and mobility changes are unrelated to HCA support.","Record that the client is noncompliant without listing changes.","Wait to see whether the symptoms resolve before mentioning them at handover."],"meaning":"Cancer care can involve nutrition and fluids, bowel function, mobility, skin protection, and symptom control. Report relevant changes and follow the plan.","source":"Day 3 PowerPoint · slide 30"},
  {"id":"hca201a-day3-notes-cancer-care-personal-priorities","scope":"day3","topic":"Supporting clients with cancer","term":"Cancer care personal priorities","prompt":"A client asks for fewer interruptions so they can rest, practise prayer, and talk privately about changes in intimacy. Which approach supports whole-person care?","answer":"Respect their preferences and privacy, accommodate what the plan allows, and share care needs with the appropriate team member.","distractors":["Put medical tasks first and record the requests only if they affect the treatment schedule.","Suggest they discuss intimacy and spiritual questions with other residents.","Ask all visitors to leave permanently so the client can rest."],"meaning":"Rest, spirituality, social support, and sexual well-being can all affect quality of life. Ask what matters to the client and respond privately.","source":"Day 3 PowerPoint · slide 30"},
  {"id":"hca201a-day3-notes-pain-and-activity-tolerance","scope":"day3","topic":"Supporting clients with cancer","term":"Pain and activity tolerance","prompt":"A client says pain worsens during their usual walk and asks to skip it. What response best supports comfort and the care plan?","answer":"Acknowledge their pain, report the change, and check how the planned activity can be adapted.","distractors":["Encourage them to complete the walk first so the team has comparable activity data.","Stop all activity permanently because pain indicates progression.","Cut the walk in half and omit reporting if the client manages that distance."],"meaning":"Pain control, rest, and activity are all care needs. Share the client's report and follow the care team's directions.","source":"Day 3 PowerPoint · slide 30"},
  {"id":"hca201a-day3-notes-objective-skin-charting","scope":"day3","topic":"HCA observation & care","term":"Objective skin charting","prompt":"Which entry best combines objective appearance and a relevant client report?","answer":"2 cm red area on the lateral left ankle; client reports itching since this morning.","distractors":["Infected rash on the left ankle, probably from the new soap.","Client has a bad rash on the leg and seems to be overreacting.","Looks allergic; client must have scratched it overnight."],"meaning":"Use location, measurements, appearance, timing, and the client's words. Do not assign a diagnosis or cause from appearance.","source":"Day 3 Comprehensive Quiz Notes · p. 9"},
  {"id":"hca201a-day3-notes-baseline-and-change","scope":"day3","topic":"HCA observation & care","term":"Baseline and change","prompt":"A client has a longstanding patch. Today it is warmer and has new drainage. Which handover helps the nurse most?","answer":"Describe what changed from baseline, when it was noticed, and the drainage and warmth observed.","distractors":["Use the previous chart entry since the patch was already known.","Record warmth alone and leave out drainage until the next observation.","Tell the nurse the patch has spread infection without describing current findings."],"meaning":"Report new features and changes from baseline rather than assuming a cause.","source":"Day 3 Comprehensive Quiz Notes · p. 9"},
  {"id":"hca201a-day3-notes-routine-practices-and-ppe","scope":"day3","topic":"HCA observation & care","term":"Routine Practices and PPE","prompt":"Before assisting with care where drainage is possible, how should the HCA decide what protection is appropriate?","answer":"Follow the required risk assessment, care plan, and workplace PPE directions, with hand hygiene at required times.","distractors":["Use gloves only for visible drainage and omit hand hygiene when gloves stay intact.","Use the same PPE for every task regardless of likely exposure.","Wait for a confirmed diagnosis before using Standard Practices."],"meaning":"Standard or Routine Practices apply to all clients. The expected exposure and policy guide PPE, which does not replace hand hygiene.","source":"Day 3 Comprehensive Quiz Notes · p. 9","reference":{"label":"Public Health Agency of Canada","url":"https://www.canada.ca/en/public-health/services/publications/diseases-conditions/routine-practices-precautions-healthcare-associated-infections/part-a.html"}},
  {"id":"hca201a-day3-notes-infection-control-equipment-and-linens","scope":"day3","topic":"HCA observation & care","term":"Infection-control equipment and linens","prompt":"A client with a contagious skin condition uses shared equipment and has soiled linens. Which approach is appropriate?","answer":"Handle the linens as directed and clean shared equipment according to agency procedure.","distractors":["Return the equipment to shared use and clean it at the end of the week.","Sort the soiled linens by shaking them out before moving them.","Apply the same household cleaning routine regardless of workplace instructions."],"meaning":"Follow local procedures for linen handling, environmental cleaning, and shared equipment.","source":"Day 3 Comprehensive Quiz Notes · p. 9"},
  {"id":"hca201a-day3-notes-scope-of-precautions","scope":"day3","topic":"HCA observation & care","term":"Scope of precautions","prompt":"A client has a new rash of unknown cause. Which action matches the HCA's role?","answer":"Report the rash and follow Standard Practices and any precautions directed by the care team.","distractors":["Independently assign isolation according to the rash's colour.","Wait for a diagnosis before taking any routine precautions.","Stop existing precautions whenever a rash looks less inflamed."],"meaning":"HCAs support infection control by reporting changes and following assigned precautions rather than making isolation decisions alone.","source":"Day 3 Comprehensive Quiz Notes · p. 9"},
  {"id":"hca201a-day3-notes-confidentiality-during-handover","scope":"day3","topic":"HCA observation & care","term":"Confidentiality during handover","prompt":"A visitor asks about a resident's skin condition while the nurse is waiting for a handover. How should the HCA respond?","answer":"Protect the resident's information and share observations privately with the care team as appropriate.","distractors":["Describe the condition to the visitor as long as the diagnosis is omitted.","Discuss the rash at the nursing station where visitors can listen.","Share the condition if the visitor already knows the resident's name."],"meaning":"Share care information only with those authorized to receive it. Provide reports in a setting that protects privacy.","source":"Day 3 Comprehensive Quiz Notes · p. 10"},
  {"id":"hca201a-day3-notes-dignity-during-skin-care","scope":"day3","topic":"HCA observation & care","term":"Dignity during skin care","prompt":"A client is embarrassed about a visible lesion and reluctant to accept care. What response best supports dignity?","answer":"Acknowledge their concern, provide privacy, and ask how they would prefer the care to proceed.","distractors":["Reassure them that the lesion is unimportant and proceed without discussing it.","Ask another client to offer advice based on a similar lesion.","Tell them the skin must be exposed because other staff need to see it."],"meaning":"Listen without blame and protect privacy while supporting the client's choices within the plan.","source":"Day 3 Comprehensive Quiz Notes · p. 10"},
  {"id":"hca201a-day3-notes-tinea-pedis-pattern","scope":"day3book","topic":"Textbook-only skin conditions","term":"Tinea pedis pattern","prompt":"Which presentation and cause are paired correctly for athlete's foot?","answer":"Peeling, burning, and itching between toes from a fungal infection","distractors":["Warm oozing crusts around the nose from a fungal infection","Thickened silvery plaques between the toes from a mite infestation","Painful one-sided blisters on the trunk from a fungus"],"meaning":"Tinea pedis is a fungal infection that commonly affects the spaces between toes.","source":"Day 3 Comprehensive Quiz Notes · p. 10"},
  {"id":"hca201a-day3-notes-tinea-pedis-spread-and-care","scope":"day3book","topic":"Textbook-only skin conditions","term":"Tinea pedis spread and care","prompt":"A client with athlete's foot uses a communal shower. Which care-plan action addresses conditions that favour spread?","answer":"Support drying between the toes as directed and avoid sharing footwear.","distractors":["Dry only the top of the foot and share footwear once it feels dry.","Keep the skin between toes moist and replace only the client's towels.","Choose a new antifungal for the client based on the size of the rash."],"meaning":"Moist communal surfaces and shared footwear can contribute to spread. Follow the plan for hygiene and care.","source":"Day 3 Comprehensive Quiz Notes · p. 10"},
  {"id":"hca201a-day3-notes-scleroderma-types","scope":"day3book","topic":"Textbook-only skin conditions","term":"Scleroderma types","prompt":"What distinguishes localized scleroderma from systemic disease in the notes?","answer":"Localized disease primarily affects skin and nearby tissue. Systemic disease may affect internal organs.","distractors":["Localized disease affects internal organs first. Systemic disease affects only a skin patch.","Localized disease is contagious. Systemic disease is acquired only from contact with blood.","Both forms affect only the skin, and the labels describe how long a patch lasts."],"meaning":"Scleroderma is an autoimmune connective tissue disorder. Systemic disease can involve organs. Localized disease primarily affects skin and sometimes underlying tissue.","source":"Day 3 Comprehensive Quiz Notes · p. 10"},
  {"id":"hca201a-day3-notes-seborrheic-keratosis-versus-suspicious-lesion","scope":"day3book","topic":"Textbook-only skin conditions","term":"Seborrheic keratosis versus suspicious lesion","prompt":"An older client asks whether a new waxy, unevenly coloured growth is a harmless seborrheic keratosis. How should the HCA respond?","answer":"Describe the observed features, report the new growth, and leave its identification to a clinician.","distractors":["Reassure them it is benign because waxy growths are never malignant.","Classify it as melanoma because the colour is uneven.","Monitor without reporting unless the growth catches on clothing."],"meaning":"Seborrheic keratoses are commonly benign and can resemble other lesions. Appearance alone is insufficient for the HCA to identify a new growth.","source":"Day 3 Comprehensive Quiz Notes · p. 10"},
  {"id":"hca201a-day3-notes-skin-tag-and-clothing","scope":"day3book","topic":"Textbook-only skin conditions","term":"Skin tag and clothing","prompt":"A small flesh-coloured projection catches on the client's zipper and starts bleeding slightly. What action fits the notes?","answer":"Protect the area from further pulling, follow the plan, and report the bleeding.","distractors":["Twist the projection off to prevent another injury.","Cover it without documenting the bleeding because skin tags are always harmless.","Apply a removal product from the client's cupboard with their permission."],"meaning":"Skin tags can catch on fasteners. Report an injury or bleeding and provide only approved care.","source":"Day 3 Comprehensive Quiz Notes · p. 10"}
];
